TRUNC=[['拉丁 truncus 截去一部分的；树干、躯干','较早的远源未定；核心可记为去掉枝杈后剩下的主体']]
TRUNK=TRUNC+[['古法语 tronc／盎格鲁法语 trunke → 英语 trunk','树干、躯干与箱体等意义分支传入']]
TRUNCATE=TRUNC+[['拉丁 truncare 截短 → 分词 truncatus → 英语 truncate','截去一部分，使变短']]
CUT=[['古法语 trenchier / tranchier 切、切开','与拉丁 truncare 的联系有说法分歧；从确定的法语起点讲起']]
TRENCH=CUT+[['古法语 trenche 切口、沟 → 英语 trench〔名词〕','切开的长口 → 沟、壕沟、海沟']]
ENTRENCH=TRENCH+[['英语 en- + trench → entrench','放进壕沟保护 → 牢牢固定、使难以改变']]
TRENCHANT=CUT+[['古法语 trenchant 正在切的 → 英语 trenchant','刃口锋利 → 言辞、分析锋利有力']]
RETRENCH=CUT+[['法语 re- + tranchier → retrancher / retrencher → 英语 retrench〔削减义〕','切掉一部分 → 削减费用、规模']]
W += [
E('trunk','/trʌŋk/','树干；躯干；大箱子；汽车后备厢；象鼻','多种常见义围绕主体、箱体或长管状部分展开，需要按场景辨认。','拉丁 truncus 树干、躯干，经古法语 tronc 和盎格鲁法语 trunke 传入。箱子义很早；象鼻义后来出现，具体联想可能还受到 trumpet 一线影响。',TRUNK+[['英语中的后续扩展','主干线路；行李箱 → 汽车行李厢；象鼻义的具体形成有不确定性']],'the trunk of a tree 是树干；put bags in the trunk 是把包放进汽车后备厢，美式常见。elephant’s trunk 是象鼻；复数 trunks 还常指泳裤或运动短裤。','a tree trunk；the trunk of the body；a car trunk；an elephant’s trunk。','branch 是分枝，trunk 是树的主体。汽车的 trunk 对应英式 boot。不要把象鼻硬想成被截掉的鼻子。',('The tree has a thick trunk and wide branches.','这棵树树干粗壮，枝条向四周展开。'),('We put the suitcases in the trunk of the car.','我们把行李箱放进汽车后备厢。'),('The elephant picked up a branch with its trunk.','大象用鼻子卷起了一根树枝。'),sources=['https://www.etymonline.com/word/trunk','https://en.wiktionary.org/wiki/trunk#English']),
E('truncate','英 /trʌŋˈkeɪt/；美 /ˈtrʌŋkeɪt/','截短；截去一部分','把末端、顶部或超出限制的部分切掉，让整个东西变短。','借拉丁 truncatus，来自 truncare 截短、截去，接 truncus；不能只看现代 trunk 就反推它是英语里新造的动词。',TRUNCATE,'truncate a message 是把消息截短；truncate a number 可说直接舍去后面的数位。也可形容会议或谈话突然缩短，常带原本内容没能完整展开的意味。','truncate a text；truncate a number；be truncated to a fixed length。','summarize 会重新组织并概括要点；truncate 常直接截去一部分，可能因此丢失重要内容。',('The app truncates long file names in the sidebar.','应用会把侧边栏里的长文件名截短显示。'),('Truncating 3.89 to one decimal place gives 3.8.','把 3.89 截到一位小数，得到 3.8。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/truncate','https://www.etymonline.com/word/truncate']),
E('truncated','英 /trʌŋˈkeɪtɪd/；美 /ˈtrʌŋkeɪtɪd/','被截短的；截去一部分的','原本更长或更完整，现在只剩下被截取后的部分。','truncate + -ed；既是动词分词，也常作形容词。',TRUNCATE+[['英语 truncate + -ed → truncated','截短 → 已被截去一部分的']],'a truncated version 是截短版；a truncated cone 是截去顶端后的圆锥形体。文本被截短不保证保留了重点，阅读时要注意是否有省略。','a truncated version；truncated text；a truncated cone；a truncated account。','abridged 通常指经过编辑压缩；truncated 更突出直接截去或没有完整保留，未必是精心删节。',('The preview showed only a truncated version of the message.','预览只显示了消息的截短版本。'),('The lampshade was shaped like a truncated cone.','灯罩的形状像一个截去顶部的圆锥。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/truncate','https://en.wiktionary.org/wiki/truncated#English']),
E('truncation','/trʌŋˈkeɪʃən/','截断；截短；截去部分的过程','把截掉一部分这件事当作过程或结果来讨论。','晚期拉丁 truncatio 来自 truncare；英语名词的记录早于动词 truncate，现代构词关系不能替代这个借入顺序。',TRUNC+[['拉丁 truncare → 晚期拉丁 truncatio → 英语 truncation','截去一部分的动作或结果']],'text truncation 是文本截短；data truncation 是数据被截去。数值计算中 truncation 与 rounding 不完全相同，直接舍去后面的数位不等于四舍五入。','text truncation；data truncation；truncation error；avoid truncation。','abbreviation 常形成简写名称；truncation 强调截去部分内容，结果不一定成为公认缩写。',('The narrow column caused unwanted text truncation.','栏宽太窄，导致文本被不必要地截短。'),('The report distinguishes rounding errors from truncation errors.','报告区分了舍入误差与截断误差。'),sources=['https://www.etymonline.com/word/truncation','https://en.wiktionary.org/wiki/truncation#English']),
E('truncheon','/ˈtrʌntʃən/','警棍；短粗棍','原先是一截粗木棍，后来常指执勤人员使用的短棍。','古法语 tronchon 一截、粗棍，通常追到重建的通俗拉丁 *truncio，与 truncus 木干相连；星号表示重建形式。',TRUNC+[['重建的通俗拉丁 *truncio → 古法语 tronchon → 中古英语 tronchoun','一段截下的木头 → 短棍'],['英语 truncheon 的后续常用义','短粗棍 → 警棍']],'carry a truncheon 是携带警棍。偏英式，现代也常用 baton；历史材料里还可以是象征职位的权杖或短棍。','a police truncheon；carry a truncheon；a wooden truncheon。','baton 范围更广，还可指指挥棒、接力棒；truncheon 常强调短粗的棍棒或警棍。',('The museum displayed a wooden police truncheon from the nineteenth century.','博物馆展出了一根十九世纪的木制警棍。'),('The officer’s truncheon hung from a loop on the belt.','警员的警棍挂在腰带的套环上。'),sources=['https://www.etymonline.com/word/truncheon','https://en.wiktionary.org/wiki/truncheon#English']),
E('trunking','/ˈtrʌŋkɪŋ/','线槽；干线布线；干线运输','把许多支线或货流集中到主干路线，也可说沿线路包住电线的槽体。','trunk 主干、箱体 + -ing；在布线、通信和物流领域分别形成固定用法。',TRUNK+[['英语 trunk + -ing → trunking','主干与容纳线路的箱槽 → 干线布线、线槽、干线运输']],'cable trunking 是整理、遮蔽电线的线槽；road trunking 是在主要节点之间进行的长距离干线运输。遇到工程文件时，要先看它说线缆外壳还是运输系统。','cable trunking；plastic trunking；road trunking；trunking services。','trucking 泛指卡车运输；trunking 的物流义强调干线段。两词拼写接近，但重点不同。',('Plastic trunking hides the cables along the wall.','塑料线槽把沿墙布设的电缆遮住了。'),('The company runs overnight trunking services between its distribution centres.','公司在各配送中心之间经营夜间干线运输。'),sources=['https://www.collinsdictionary.com/dictionary/english/trunking','https://en.wiktionary.org/wiki/trunking#English']),
E('trench','/trentʃ/','沟；壕沟；海沟；挖沟','在地面或海底形成一条长而窄的深口，好像表面被切开。','古法语 trenche 切口、沟，来自 trenchier 切；远源常联系拉丁 truncare，也有其他解释，不能当已确认的直系。',TRENCH+[['古法语 trencher 切 → 英语 trench〔动词〕','切入、挖成沟；不必只由英语名词转成']],'dig a trench 是挖沟；trenches 可指战壕；an ocean trench 是海沟。动词 trench the ground 是在地面开沟。','dig a trench；a drainage trench；trench warfare；an ocean trench。','ditch 常是较一般、较浅的沟；trench 常突出长窄且较深，但具体界线随工程语境而变。',('The workers dug a trench for the water pipe.','工人挖了一条沟，用来铺设水管。'),('The documentary follows soldiers living in the trenches.','纪录片记录了生活在战壕中的士兵。'),sources=['https://www.etymonline.com/word/trench','https://en.wiktionary.org/wiki/trench#English']),
E('tranche','常用 /trɑːnʃ/；亦 /træntʃ/','一部分；一批；一档〔常用于资金、证券〕','把一个大整体像切面包一样分成几份，其中每一份都可单独安排。','法语 tranche 一片、一段，接 trancher 切；与 trench 同接法语切的支线，较早远源仍有争议。',CUT+[['法语 tranche 一片 → 英语 tranche','切下来的一份 → 分批资金或分档证券']],'the first tranche of funding 是第一批资金；a debt tranche 可以是按偿付次序、风险等划出的债务份额。不一定表示每份金额相等。','a tranche of funding；the first tranche；a debt tranche；release a tranche。','instalment 常强调分期支付的一期；tranche 更强调从整体划出的一部分，也可按风险类别而非时间划分。',('The first tranche of funding will support the pilot project.','第一批资金将用于支持试点项目。'),('The agreement divides the payment into three tranches.','协议把付款分成三批。'),sources=['https://www.etymonline.com/word/tranche','https://en.wiktionary.org/wiki/tranche#English','https://www.oxfordlearnersdictionaries.com/definition/english/tranche']),
E('trenchant','/ˈtrentʃənt/','犀利的；有力而明确的','话像锋利的刀，切开含糊之处，直接碰到问题的关键。','古法语 trenchant 是 trenchier 切的现在分词；英语从刃口锋利引申为言论、批评或分析有力。',TRENCHANT,'trenchant criticism 是尖锐有力的批评；a trenchant analysis 是抓住要害的分析。通常描述表达内容，不是泛说一个人脾气凶。','trenchant criticism；a trenchant analysis；a trenchant observation。','harsh 可以只是严厉甚至刻薄；trenchant 还强调清楚、有效、切中问题。',('The essay offers a trenchant critique of the policy’s assumptions.','文章对这项政策的前提提出了犀利批评。'),('Her trenchant observation changed the direction of the discussion.','她一句切中要害的话改变了讨论方向。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/trenchant','https://en.wiktionary.org/wiki/trenchant#English']),
E('trenchantly','/ˈtrentʃəntli/','犀利地；鲜明有力地','表达时下刀很准，清清楚楚指出问题，而不是绕着说。','trenchant + -ly；把锋利、切中要害的评价用于说话、写作和分析。',TRENCHANT+[['英语 trenchant + -ly → trenchantly','锋利有力的 → 以明确、切中要害的方式']],'argue trenchantly 是鲜明有力地论证；trenchantly expressed views 是表达犀利的观点。偏正式，适合评论文章或辩论。','argue trenchantly；write trenchantly；trenchantly expressed。','loudly 是声音大；trenchantly 说表达的力度和清晰度，不靠音量判断。',('She argued trenchantly that the figures did not support the conclusion.','她鲜明有力地指出，这些数字并不支持那个结论。'),('The review trenchantly exposes the novel’s weak structure.','评论犀利地揭示了小说结构上的薄弱之处。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/trenchantly','https://en.wiktionary.org/wiki/trenchantly#English']),
E('entrench','/ɪnˈtrentʃ/','使牢固确立；使根深蒂固；用壕沟保护','原来像挖壕沟守住阵地，后来变成让某种权力、观念或习惯很难被动摇。','英语 en- 放入、使处于 + trench 壕沟；先有军事防护义，再发展出牢固确立的比喻。',ENTRENCH,'entrench an inequality 是让不平等更难消除；entrench a right 可以是牢固确立某项权利。词本身不保证被固定下来的是好事还是坏事。','entrench power；entrench inequality；entrench an attitude；be firmly entrenched。','establish 是建立；entrench 进一步强调难以改变或推翻。常带根深蒂固的画面。',('The reform could entrench the power of existing leaders.','这项改革可能进一步巩固现有领导者的权力。'),('Repeated small decisions can entrench an unfair system.','一次次小决定可能让不公平的制度变得根深蒂固。'),sources=['https://www.etymonline.com/word/entrench','https://www.oxfordlearnersdictionaries.com/definition/english/entrench','https://en.wiktionary.org/wiki/entrench#English']),
E('entrenched','/ɪnˈtrentʃt/','根深蒂固的；牢固确立的','已经占稳位置、扎下根，靠一两次劝说或小变化很难移走。','entrench + -ed；末尾 -ed 在 /tʃ/ 后读 /t/，常用分词形容词描述牢固状态。',ENTRENCH+[['英语 entrench + -ed → entrenched','使牢固 → 已根深蒂固、难以改变的']],'entrenched attitudes 是固有观念；entrenched interests 是牢牢占据位置的既得利益。常与 deeply、firmly 连用。','deeply entrenched；entrenched interests；entrenched attitudes；firmly entrenched。','popular 只是流行或受欢迎；entrenched 说位置牢固。某种做法即使不受欢迎，也可能很难改变。',('The new manager faced deeply entrenched habits.','新经理面对的是根深蒂固的工作习惯。'),('The proposal threatened entrenched interests within the industry.','提案触动了行业内牢固的既得利益。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/entrench','https://en.wiktionary.org/wiki/entrenched#English']),
E('entrenchment','/ɪnˈtrentʃmənt/','牢固确立；根深蒂固；壕沟防御工事','把某种状态固定下来、使其难以改变的过程或结果。','entrench + -ment；由壕沟保护的动作发展出制度、利益和观念的固化。',ENTRENCH+[['英语 entrench + -ment → entrenchment','使牢固 → 固定下来的过程或状态；也指防御工事']],'the entrenchment of privilege 是特权固化；the entrenchment of rights 是权利获得稳固保障。军事材料里还保留壕沟防御设施义。','the entrenchment of；institutional entrenchment；political entrenchment。','entrenchment 强调加固某种位置；retrenchment 常指缩减开支或规模，不能仅因词形近就互换。',('The report warns of the entrenchment of economic inequality.','报告警告经济不平等正变得难以改变。'),('The historian mapped the army’s entrenchments around the town.','历史学家绘出了军队在城镇周围的壕沟防御工事。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/entrenchment','https://en.wiktionary.org/wiki/entrenchment#English']),
E('retrench','/rɪˈtrentʃ/','削减开支；缩减规模；裁减人员','原来的摊子铺得太大，现在把一部分切回去，减轻负担。','削减义经法语 retrencher / retrancher，re- 回 + tranchier 切；军事重新筑壕沟的旧义有另一条形成路线。',RETRENCH,'retrench when sales fall 是销量下降时收缩开支；一些地区英语中 retrench workers 是裁员。现代商业阅读里重点是规模和成本收缩。','retrench spending；retrench operations；retrench workers；be forced to retrench。','entrench 是让位置更牢；retrench 常是削减。retreat 是退却，retrench 可通过减少支出发生，并不一定搬离原地。',('After years of expansion, the company began to retrench.','多年扩张之后，公司开始收缩规模。'),('The factory retrenched workers after losing a major contract.','工厂失去一份大合同后裁减了工人。'),sources=['https://www.etymonline.com/word/retrench','https://en.wiktionary.org/wiki/retrench#English','https://www.oxfordlearnersdictionaries.com/definition/english/retrench']),
E('retrenchment','/rɪˈtrentʃmənt/','开支削减；规模收缩；裁员','把削减预算、人员或业务范围当成一个整体过程。','削减义有法语 retrenchement / retranchement 的名词借入路线，也受 retrench + -ment 影响；更早军事工事义另有历史，不能都画成现代动词派生。',CUT+[['法语 retrencher / retrancher → retrenchement / retranchement → 英语 retrenchment〔削减义〕','切去一部分 → 开支或规模收缩'],['英语 retrench + -ment 的构词关系强化','节约开支；在部分地区英语中也说裁员']],'a period of retrenchment 是收缩期；financial retrenchment 是财政或财务紧缩。具体是不是裁员，要看地区用法和上下文。','financial retrenchment；a period of retrenchment；staff retrenchment。','austerity 常说较广泛的紧缩政策或生活方式；retrenchment 更着眼于把开支、人员、业务切减的行动。',('The budget marks a period of retrenchment after rapid growth.','这份预算标志着快速增长之后的收缩期。'),('Employees feared that the merger would lead to retrenchment.','员工担心合并会导致裁员。'),sources=['https://www.etymonline.com/word/retrenchment','https://en.wiktionary.org/wiki/retrenchment#English']),
]
