DEFERRED={'depredate':'较少见动词，通用阅读优先 prey、plunder 和 depredation。','anadromous':'较专门鱼类洄游术语，暂略。','monodromy':'专门数学术语，暂略。','antidromic':'专门神经生理形容词，暂略。','catadromous':'较专门鱼类洄游术语，暂略。','diadromous':'较专门洄游分类术语，暂略。','dromaeosaurid':'专门恐龙分类名词，暂略。','heterodromous':'较冷门生物或方向术语，暂略。','loxodrome':'专门航线几何词，暂略。','trunnion':'较专门机械支承部件名，暂略。','detruncate':'古旧或罕用截断动词，优先 truncate。','detruncation':'较冷门截除名词，优先 truncation。','obtruncate':'古旧或罕用截断动词，暂略。','obtruncation':'古旧截断名词，暂略。','omnitruncation':'专门多面体几何运算，暂略。','tranchet':'专门考古石器词，暂略。','trenchancy':'较少见抽象名词，优先 trenchant。','intrench':'旧拼写，通用学习采用 entrench。','intrenchment':'旧拼写，通用学习采用 entrenchment。'}
PAN_ROOT=dict(id='C0952',meaning='潘神；突发的恐慌',core='古人在旷野中听见怪响、突然惊慌，把这种可传染的恐惧归到潘神头上；后来只剩下普通的恐慌意思。',image='希腊神名 Pan → panikos 属于潘神的 → 法语 panique → 英语 panic 形容词、名词、动词 → panicky、panicked、panicking。',intro='这页不是 pan- 全部。panic 来自潘神的名字，从神话中的惊恐走到日常的别慌、市场恐慌、慌乱反应。了解名字的背景即可，不必把今天每次紧张都解释为神灵作用。',forms='panic 加 -ed、-ing、-y 时添 k：panicked、panicking、panicky。这样保留 /k/ 的声音。panicked 的末尾读 /kt/，不另加一个音节。',branches=[['恐慌与行动','panic'],['慌乱的感觉与状态','panicky, panicked'],['正在发生的反应','panicking']],contrasts='nervous 常只是紧张；panicky 更接近慌乱。panic 的神名来源与表示全部的 pan-、锅 pan 不应混同。',practice='用 panic 描写一次突然着急；把 panic 变成过去式与进行时，解释为何加 k；比较 nervous 与 panicky 的语气。',words=[w for w in ASSIGN['roots'][120]['family'] if w not in DEFERRED],exclude={})
STIN_ROOT=dict(id='C1426',meaning='固定；使牢固；确定方向',core='先把某件事牢牢定住：定住去向是指定或注定，守住态度不动就会显得顽固。',image='与拉丁 stare 站立相关的 -stinare → destinare 确定、安排 → destine、destiny、destination；obstinare 固执坚持 → obstinate 一组。',intro='destination 是已经选定的目的地；destiny 是被想成已定的命运；destined 也可以只说货物预定运往哪里。另一支 obstinate 描写态度硬、不肯改变。它们共享固定这一画面，却不是互相替换的词。',forms='-stinare 是历史构词中与站立、稳固相关的成分，不是现代英语的独立动词。destiny 经法语分词转名词，destination 接拉丁名词，两条路线分开。',branches=[['确定去向','destine, destined, destination'],['人生走向','destiny'],['态度不肯改变','obstinate, obstinacy, obstinately']],contrasts='destination 通常是地点，destiny 是命运。destined for export 只是指定用途，不是在说神秘预言。determined 可以称赞坚定，obstinate 常批评固执。',practice='分别用 destined for 说一批货物和一个人的前途；比较 destiny 与 destination；解释 obstinate 和 determined 的评价差别。',words=[w for w in ASSIGN['roots'][121]['family'] if w not in DEFERRED],exclude={})
PRED_ROOT=dict(id='C1117',meaning='猎物；掠获物；捕食与掠夺',core='一方主动寻找并取走，另一方成了它的目标。放在自然界是捕食关系，放在人类社会常是利用和侵害。',image='拉丁 praeda 猎物、战利品 → 法语 preie → prey；praedari 掠取 → praedator、praedatorius、praedatio → predator、predatory、predation。',intro='prey 是被捕食的一方，predator 是捕食的一方，predation 是过程。动物捕食是生态关系，不能直接套上人类道德判断；predatory 用来形容人或机构时，则常批评利用弱者。',forms='prey 经法语演变，拼写与 pred- 看起来不太像，但确实同源。prey 和 pray 同音不同源。predation 的重音在 /deɪ/，predator 的重音在首音节。',branches=[['捕食关系中的双方','prey, predator'],['行为性质与过程','predatory, predation'],['劫掠造成的破坏','depredation']],contrasts='cooperation 是合作，predatory behaviour 常是利用他人的弱点。predation 在生态语境中性，depredation 常从受损一方强调破坏。pray 祈祷不能用 prey 替代。',practice='用 prey 和 predator 描述同一场捕食关系；解释 prey on someone’s fears；比较 predation 与 depredation 的观察角度。',words=[w for w in ASSIGN['roots'][122]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][122]['family'] if w in DEFERRED})
DROM_ROOT=dict(id='C0346',meaning='跑；路线；跑道与场地',core='从跑这个动作出发，可以想到一起跑、往回跑、马跑的场地、自行车跑的场地。',image='希腊 dramein 跑、dromos 跑道 → syn- 一起 + dromos → syndrome；palin 向回 + dromos → palindrome；hippo- 马、vélo 自行车 + -drome → 场地名称。',intro='syndrome 的一起跑，变成一组共同出现的表现；palindrome 的向回跑，变成倒着读仍相同的回文。hippodrome 原指赛马、战车场，如今有些剧院仍用这个名字。dromedary 最初强调善于奔走的骆驼。',forms='dram- 与 drom- 在这页对应希腊跑的词形；不要仅因拼写接近，就把 drama 戏剧也放进来，后者接的是行动的另一条来源。-drome 常表示路线或活动场地。',branches=[['一同出现','syndrome'],['正着读、倒着读','palindrome, palindromic'],['奔跑与交通场地','hippodrome, velodrome, aerodrome'],['奔走的动物','dromedary']],contrasts='symptom 是单个症状，syndrome 是一组表现。palindrome 不等于任意字母重排。aerodrome 是飞行场，hippodrome 与马和演出相关，velodrome 是自行车赛车场。',practice='找一个回文词并从两头读；根据前半部分判断三种 -drome 场地；解释 syndrome 的共同出现为什么不必意味着单一病因。',words=[w for w in ASSIGN['roots'][123]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][123]['family'] if w in DEFERRED})
TRUNC_ROOT=dict(id='C1562',meaning='截短；去掉一部分；主体；法语切开支线',core='把枝杈、顶部或末端切去，留下主体。另一组法语切开词让人想到沟、切片和锐利言辞，但它与拉丁根的远源联系仍有分歧。',image='拉丁 truncus → trunk；truncare 截短 → truncate、truncation。并列古法语 trenchier 切：trenche → trench，tranche → 一部分，trenchant → 犀利，retrancher → retrench。',intro='trunk 能说树干、箱子、汽车后备厢和象鼻，不能都硬翻成截断。truncate 是截短，truncation 的英语记录更早。trench、tranche、trenchant 一线确定接古法语切，传统常把它联系到 truncare，但也有不同远源解释，因此在这里保留为有边界的关联支线。',forms='truncate 常见英式后重音、美式前重音；truncation 的重音在 /keɪ/。tranche 保留较明显的法语色彩，trench 已英语化。entrenched 末尾读 /tʃt/，不把 -ed 额外读成一节。',branches=[['主体、箱体与干线','trunk, trunking, truncheon'],['截去一部分','truncate, truncated, truncation'],['法语切开、切成份的支线','trench, tranche'],['锋利言辞','trenchant, trenchantly'],['挖沟守住 → 难以动摇','entrench, entrenched, entrenchment'],['切减规模与支出','retrench, retrenchment']],contrasts='entrench 是使位置更牢，retrench 常是缩减规模。truncate 直接截去部分，summarize 是概括要点。truncation 不等于四舍五入。trench 的远源争议不能靠几个相似字母解决。',practice='用 trunk 分别说树、汽车和大象；把一段长文字 truncate 后说明丢了什么；比较 entrenched interests 与 financial retrenchment。',words=[w for w in ASSIGN['roots'][124]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][124]['family'])+ASSIGN['roots'][124]['unmatched'] if w in DEFERRED})
